INSERT INTO "listings" VALUES(1080,'porsche_finder','RNPWK3','WP0AC2A97TS288144',103,'https://finder.porsche.com/us/en-US/details/porsche-911-gt3-with-touring-package-preowned-RNPWK3','17642','active','2026-11-14T11:46:34Z','2026-11-14T16:09:09Z','2026-11-14T16:09:09Z',0,0,NULL,339255.0,531,'{"accident_free":null,"carfax_clean_title":null,"condition":"used","cpo":true,"dealer_fees_listed":2675,"documents":{"build_sheet_available":true,"car_pass_url":null,"window_sticker_available":true},"exterior_color":"White","exterior_hex":"#dce0dc","extra":{"capture_level":"full","commission_number":"J38399","exterior_color_code":"0Q","inventory_id":"6a97d69eba8d0370db804f8b","listed":true,"model_code":"992822","via":"browser capture"},"fee_items":[{"amount":85,"label":"Doc Fee"},{"amount":1295,"label":"Reviver Plate"},{"amount":1295,"label":"Zurich Shield"}],"generation":"992.2","has_equipment_list":true,"highlights":["sport-exhaust","lifting-system","rear-axle-steering","reversing-camera","front-led-matrix","sports-seats"],"interior_color":"Leather Interior in Black with Fabric Seat Centers","issues":[],"mileage":531,"one_owner":null,"options":[{"code":"04F","group":"Packages","name":"Lightweight Package in Black"},{"code":"6FP","group":"Exterior","name":"Exterior Mirror Upper Trims in Carbon Fiber"},{"code":"5M2","group":"Exterior","name":"Roof in Exposed Carbon Fiber"},{"code":"G1C","group":"Engine, transmission and chassis","name":"7-speed Porsche Doppelkupplung (PDK)"},{"code":"2UH","group":"Engine, transmission and chassis","name":"Front Axle Lift System"},{"code":"1LX","group":"Engine, transmission and chassis","name":"Porsche Ceramic Composite Brakes (PCCB) with Calipers in High Gloss Black"},{"code":"1NX","group":"Wheels","name":"Wheels Painted in Satin Black"},{"code":"F37","group":"Wheels","name":"20\"/21\" 911 GT3 Forged Magnesium Lightweight Wheels"},{"code":"Q1J","group":"Interior","name":"Adaptive Sport Seats Plus (18-way)"},{"code":"3UG","group":"Interior","name":"Rear Seats"},{"code":"6E2","group":"Interior","name":"Center Console Lid with Porsche Crest"},{"code":"6NA","group":"Interior","name":"Roof Lining in Race-Tex"},{"code":"QE3","group":"Interior","name":"Storage Net in Passenger Footwell"},{"code":"8JU","group":"Lighting and vision","name":"HD-Matrix Design LED Headlights in Black"},{"code":"8VH","group":"Lighting and vision","name":"Exclusive Design Taillights"},{"code":"UD1","group":"Lighting and vision","name":"Under Door Puddle Light Projectors"}],"origin_site":null,"photos":[],"photos_advertised":37,"photos_are_real":true,"previous_owners":null,"price":339255,"price_as_listed":341930,"scope":"17642","seller":{"city":"Fresno","kind":"porsche_dealer","name":"Porsche Fresno","partner_number":"4500154","phone":null,"source_seller_id":"17642","state":"CA","street":"7121 N. Palm Avenue","website":null,"zip":"93650"},"seller_comment":"2026 Porsche 911 GT3 Touring | Porsche Approved Certified | One Owner | Clean CARFAX\n\nEXTERIOR: White\nINTERIOR: Leather Interior in Black with Fabric Seat Centers\n\nThis 2026 Porsche 911 GT3 Touring is offered as a Porsche Approved Certified Pre-Owned vehicle, presenting an extraordinarily rare specification built around the full Lightweight Package — one of the most focused, purpose-built GT3 Tourings available anywhere. Carfax confirms a true one-owner history with no accidents, no structural damage, no airbag deployment, and a guaranteed clean title.\n\nFactory Options & Build Highlights:\n\nLightweight Package in Black including Roof in Exposed Carbon Fiber and 20\"/21\" 911 GT3 Forged Magnesium Lightweight Wheels\nPorsche Ceramic Composite Brakes (PCCB) with Calipers in High Gloss Black\n7-speed Porsche Doppelkupplung (PDK)\nFront Axle Lift System\nExterior Mirror Upper Trims in Carbon Fiber\nWheels Painted in Satin Black\nAdaptive Sport Seats Plus (18-way)\nRear Seats\nCenter Console Lid with Porsche Crest\nRoof Lining in Race-Tex\nHD-Matrix Design LED Headlights in Black\nExclusive Design Taillights\nStorage Net in Passenger Footwell\nUnder Door Puddle Light Projectors\n\nVehicle Overview:\n\nFinished in White over a Black leather interior with fabric seat centers, this GT3 Touring presents one of the most extraordinary specifications available, anchored by the full Lightweight Package. The Roof in Exposed Carbon Fiber and 20\"/21\" 911 GT3 Forged Magnesium Lightweight Wheels shed meaningful weight while putting this Touring''s motorsport-derived engineering on full display, making it one of the lightest, most track-capable GT3 Tourings in existence.\n\nPorsche Ceramic Composite Brakes with High Gloss Black calipers deliver uncompromising stopping power, while the 7-speed Porsche Doppelkupplung (PDK) transmission brings lightning-quick shifts to complement the GT3''s naturally aspirated flat-six. A Front Axle Lift System adds genuine everyday usability, while genuine Rear Seats offer added versatility without sacrificing the car''s track-focused intent. Carbon Fiber exterior mirror trims and Satin Black-painted wheels further the purposeful, motorsport-inspired aesthetic throughout.\n\nInside, Race-Tex roof lining, a Center Console Lid with Porsche Crest, and 18-way Adaptive Sport Seats Plus create a driver-focused cabin built for serious performance, while HD-Matrix Design LED Headlights in Black and Exclusive Design Taillights round out a specification that is as visually striking as it is track-capable.\n\nOffered here as a Porsche Approved Certified Pre-Owned vehicle, this GT3 Touring carries the added confidence of Porsche''s CPO multi-point inspection, making it an exceptionally rare opportunity to own one of the most comprehensively equipped GT3 Tourings available.\n\nTHE 911 GT3 TOURING. WHITE OVER BLACK LEATHER WITH FABRIC SEAT CENTERS. PORSCHE APPROVED CERTIFIED PRE-OWNED EXAMPLE EQUIPPED WITH THE FULL LIGHTWEIGHT PACKAGE, PCCB, AND FORGED MAGNESIUM WHEELS. THE ULTIMATE EXPRESSION OF GT3 TOURING.","service_history":"Yes, every service done in Porsche Center","source":"porsche_finder","source_days_on_market":null,"source_first_seen":null,"source_listing_id":"RNPWK3","source_previous_price":null,"standard_equipment":["Touring Package","GT3 with Touring Package Specific Equipment","Side Skirts in Black","Without roof rails","Lower Front Fascia","Deletion of Model Designation on Rear","GT3-specific rear deck lid","Coupe with two seats","Pedestrian safety","Exterior Mirror Lower Trim in Exterior Color and Base in Black","4.0-Liter Naturally Aspirated Boxer 6","Power Steering Plus","Rear Axle Steering with Sport Setup","Rear-wheel drive","PASM Sport Suspension","16.6 gal. fuel tank","Suspension","6-speed GT Sport Manual Transmission","Braking system","Wheel center caps with monochromatic Porsche Crest","Tire Pressure Monitoring System (TPMS) with Track Mode","Tire Sealing Compound and Air Compressor","Wheels Painted in Silver","20\"/21\" 911 GT3 Wheels","Seat belts","GT Sport Steering Wheel in Leather","Heated Seats (Front)","Steering Wheel Column with Manual Adjustments","Porsche Crest on Headrests (Front)","Without Sport Chrono stopwatch dial","GT-Specific Gear Lever and Boot Cover in Black Leather","Interior Trim in Black","Pedals and footrest in stainless steel","Sun visors for driver and front passenger","Sport Seats Plus (4-way)","Roof lining and A-/B-/C-pillars in fabric","Sound Package Plus","Navigation Module for Porsche Communication Management (PCM)","Smartphone compartment with wireless charging (up to 15 W)","Voice Control","USB-C ports","SiriusXM® Antenna","Electrical adjustable and heated exterior mirrors","Auto-Dimming Mirrors","Windshield with Grey Top Tint","Lightweight and Noise Insulated Glass (Front and Rear)","Matrix Design LED Headlights","Taillight Strip with \"PORSCHE\" Logo","Reversing Camera","2-Zone Automatic Climate Control","Particle/Pollen Filter with Active Carbon Filter","HomeLink®","Traffic Sign Recognition","Rain sensing wipers with intermittent wipe","Interior lighting","Cruise Control","Alarm system with interior monitoring","Non-Smoking Package","Alcohol interlock preparation","Airbags","Porsche Entry","Warn and Brake Assist","Driver Awareness Detection","Emergency call systems eCall and bCall"],"stock_number":"6975P","title":"2026 Porsche 911 GT3 Touring","transmission":"pdk","transmission_raw":"PDK (Automatic)","url":"https://finder.porsche.com/us/en-US/details/porsche-911-gt3-with-touring-package-preowned-RNPWK3","variant":"gt3_touring","vin":"WP0AC2A97TS288144","warranty":[{"duration":"24 months","label":"Porsche Approved Warranty","type":"PORSCHE_APPROVED_WARRANTY"},{"duration":"24 months","label":"Porsche Roadside Assistance","type":"ASSISTANCE"}],"year":2026}');
